package com.netbanking.account.dto.response; import com.netbanking.account.entity.*; import java.math.BigDecimal; import java.time.LocalDateTime; public record LedgerResponse(Long id,String transactionReference,String entryReference,EntryType entryType,BigDecimal amount,BigDecimal balanceAfter,LocalDateTime createdAt){public static LedgerResponse from(AccountLedger l){return new LedgerResponse(l.getId(),l.getTransactionReference(),l.getEntryReference(),l.getEntryType(),l.getAmount(),l.getBalanceAfter(),l.getCreatedAt());}}
